int main() {
    bool conditionA = true;
    bool conditionB = false;

    // Using alternative operator keywords 'and', 'or', 'not'
    if (conditionA and not conditionB) {
        std::cout << "Condition met: conditionA is true AND conditionB is false.\n";
    }

    if (conditionA or conditionB) {
        std::cout << "Condition met: conditionA OR conditionB is true.\n";
    }

    // Bitwise alternative representations
    unsigned int flags = 0b0101;
    unsigned int mask  = 0b0011;

    unsigned int andResult = flags bitand mask;
    unsigned int orResult  = flags bitor mask;
    unsigned int xorResult = flags xor mask;

    std::cout << "flags bitand mask: " << andResult << "\n";
    std::cout << "flags bitor mask:  " << orResult  << "\n";
    std::cout << "flags xor mask:    " << xorResult << "\n";

    return 0;
}
